def login(base_url: str, employee_code: str, password: str) -> str:
    root = base_url.rstrip("/")
    status, payload = api_json(
        "POST",
        f"{root}/api/auth/login",
        body={"employee_code": employee_code, "password": password},
    )
    if not isinstance(payload, dict):
        raise RuntimeError(f"登录失败 HTTP {status}: {payload}")
    token = _auth_token(payload)
    if status == 200 and token and payload.get("status") in (None, "authenticated"):
        return token
    if payload.get("status") == "enroll_required":
        raise RuntimeError("人效通还在要求绑定验证器，请先在网页上完成绑定")
    if status != 200 or payload.get("status") != "verify_required":
        raise RuntimeError(f"登录失败 HTTP {status}: {_public_payload(payload)}")
    challenge = payload.get("challenge_token")
    if not isinstance(challenge, str) or not challenge:
        raise RuntimeError("登录需要验证码，但响应里没有 challenge_token")
    code = totp_code(read_mfa_secret(employee_code))
    status2, payload2 = api_json(
        "POST",
        f"{root}/api/auth/mfa/verify",
        body={"challenge_token": challenge, "code": code},
    )
    token2 = _auth_token(payload2)
