async def send_unreplied_today(client) -> int:
    """监听中断期间漏掉的关键词，25 分钟内补回一次。"""
    if not CHAGANG_REPLY_ENABLED or not os.path.isfile(CHAGANG_OBSERVE_PATH):
        return 0
    now = datetime.now(SHANGHAI)
    pending = []
    with _lock:
        with open(CHAGANG_OBSERVE_PATH, encoding='utf-8') as f:
            for raw in f:
                raw = raw.strip()
                if not raw:
                    continue
                try:
                    rec = json.loads(raw)
                except json.JSONDecodeError:
                    continue
                keyword = rec.get('would_reply')
                if rec.get('sent') or not keyword:
                    continue
                try:
                    ts = datetime.strptime(rec.get('ts') or '', '%Y-%m-%d %H:%M:%S').replace(tzinfo=SHANGHAI)
                except ValueError:
                    continue
                age = (now - ts).total_seconds()
                if 0 <= age <= 25 * 60:
                    pending.append(rec)
    sent_n = 0
    for rec in pending:
        keyword = rec['would_reply']
        try:
            await client.send_message(int(rec['chat_id']), keyword, reply_to=None)
        except Exception as exc:
            log.error('[chagang] catch-up send failed msg=%s: %s', rec.get('message_id'), exc)
            continue
        with _lock:
            _mark_sent(rec.get('chat_id'), rec.get('message_id'))
        sent_n += 1
        log.info('[chagang] caught up msg=%s keyword=%r', rec.get('message_id'), keyword)
    return sent_n


