async def _typing_loop(update: Update, done: asyncio.Event):
    """跑 agent 时刷 typing，接近 IDE「正在想」的体感；不往聊天刷字。"""
    bot = update.get_bot()
    chat_id = update.effective_chat.id
    while not done.is_set():
        try:
            await bot.send_chat_action(chat_id=chat_id, action='typing')
        except Exception:
            pass
        try:
            await asyncio.wait_for(done.wait(), timeout=4.0)
            return
        except asyncio.TimeoutError:
            continue


async def _progress_nudge_loop(update: Update, done: asyncio.Event):
    """长任务进度提醒（仅私聊）。SLOW_NUDGE_SEC<=0 时关闭，避免占满 TG。"""
    if SLOW_NUDGE_SEC <= 0 or _is_group_chat(update):
        await done.wait()
        return

